@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="row g-2 mb-3">
        <div class="col"><div class="card text-center p-2"><strong>Total</strong><span>@_allTasks.Count</span></div></div>
        <div class="col"><div class="card text-center p-2"><strong>To Do</strong><span>@TasksForColumn("To Do").Count</span></div></div>
        <div class="col"><div class="card text-center p-2"><strong>In Progress</strong><span>@TasksForColumn("In Progress").Count</span></div></div>
        <div class="col"><div class="card text-center p-2"><strong>Done</strong><span>@TasksForColumn("Done").Count</span></div></div>
        <div class="col"><div class="card text-center p-2 text-danger"><strong>Overdue</strong><span>@_allTasks.Count(t => t.DueDate.Date < DateTime.Today)</span></div></div>
    </div>

    <!-- Search -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchTerm" @bind:event="oninput" />
    </div>

    <!-- Columns -->
    <div class="row g-3">
        @foreach (var column in _columns)
        {
            var filtered = FilteredTasksForColumn(column);
            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@column</strong>
                        <span class="badge bg-secondary">@filtered.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2" style="min-height:200px;">
                        @foreach (var task in filtered)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="mb-1 text-muted small">@task.Assignee</p>
                                    <span class="badge @PriorityClass(task.Priority) me-1">@task.Priority</span>
                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    <div class="mt-2 d-flex gap-1">
                                        @if (ColumnIndex(column) > 0)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    disabled="@_moving"
                                                    @onclick="() => MoveTaskAsync(task.Id, _columns[ColumnIndex(column) - 1])">
                                                ← Move Left
                                            </button>
                                        }
                                        @if (ColumnIndex(column) < _columns.Length - 1)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    disabled="@_moving"
                                                    @onclick="() => MoveTaskAsync(task.Id, _columns[ColumnIndex(column) + 1])">
                                                Move Right →
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_showForm == column)
                        {
                            <div class="card border-primary mt-auto">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2"
                                           @bind="_newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-sm btn-primary" disabled="@_saving"
                                                @onclick="() => SaveTaskAsync(column)">Save</button>
                                        <button class="btn btn-sm btn-outline-secondary"
                                                @onclick="CancelForm">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-primary mt-auto"
                                    @onclick="() => ShowAddForm(column)">+ Add Task</button>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchTerm = string.Empty;

    // Move state
    private bool _moving;

    // Add-task form state
    private string? _showForm;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _error = null;
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> TasksForColumn(string status)
        => _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> FilteredTasksForColumn(string status)
        => _allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(_searchTerm) ||
                         t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private static int ColumnIndex(string column) => column switch
    {
        "To Do" => 0,
        "In Progress" => 1,
        _ => 2
    };

    private static string PriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        _moving = true;
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = _allTasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                _allTasks[idx] = _allTasks[idx] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _moving = false;
        }
    }

    private void ShowAddForm(string column)
    {
        _showForm = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelForm() => _showForm = null;

    private async Task SaveTaskAsync(string column)
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
            return;

        _saving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
            // If the service doesn't return the task in the requested column, adjust status
            var task = created.Status == column ? created : created with { Status = column };
            if (task.Status != created.Status)
            {
                await TaskService.UpdateTaskStatusAsync(task.Id, column);
            }
            _allTasks.Add(task);
            _showForm = null;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

